// test/contract/contract-conformance.test.ts
//
// Wave A3 contract drift guard.
//
// Asserts — at COMPILE TIME — that this library's public types and the
// frames its hooks send/parse stay conformant with the canonical client-
// frame declarations generated by @connorhoehn/event-catalog (v0.3.58+,
// `client-frames` subpath: 31 outbound `client.<service>.<action>` frames
// + the inbound `ws.*` hook-contract + gateway send-back declarations). EC
// v0.3.58 declared the gateway send-back envelopes per service ground truth
// (divergence note b); §3b asserts the hooks' parsers against them. EC v0.3.56
// corrected
// the chat/presence/reaction/activity declarations against gateway service
// ground truth (hub#1497): chat verb is 'join' (not 'subscribe'), reaction
// verb is 'send' (not 'react'), presence.subscribe requires channel,
// presence.set requires status (channel deprecated; pinning via channels[]),
// chat.history limit optional, activity keyed on channelId with verb
// 'getHistory'. EC v0.3.57 backfilled the remaining gateway-verified verbs
// (chat.leave, reaction.subscribe/unsubscribe/getAvailable,
// presence.get/heartbeat), so every verb in the verified handleAction sets
// is now declared and asserted below.
//
// How it runs:
//   - `npm run check:contract` — standalone tsc pass (tsconfig.contract.json).
//   - `npm test` — ts-jest type-checks this file on every suite run, so any
//     drift between the local types and the EC-generated unions fails CI-less
//     local runs too. The runtime `describe` block below is intentionally
//     trivial; the assertions are the types.
//
// Design notes:
//   - The library's public types in src/client/types.ts are deliberately NOT
//     aliased to EC types: event-catalog is a devDependency only, and the
//     built dist (.js and .d.ts) must stay free of event-catalog references
//     so consumers of the prebuilt dist need no new dependency. Conformance
//     is therefore asserted here instead of by aliasing.
//   - Outbound frames also carry inline `satisfies ClientFramePayload<...>`
//     annotations at every hook send-site, so send-site drift fails the main
//     build as well. This file additionally pins the FULL outbound frame-name
//     set, so a frame ADDED to (or removed from) event-catalog fails here and
//     forces an explicit decision in this library.
//   - EC inbound payloads model the PRE-PARSE wire (fields the gateway may
//     omit are optional); the local public types are POST-PARSE (the hooks'
//     as*() guards fill defaults, so fields are required). Full mutual
//     assignability is therefore asserted field-wise + by key-set parity,
//     not by whole-object assignability in the EC→local direction.

import type {
  ClientFramePayloadMap,
  ClientFramePayload,
  ChatOutboundFrame,
  PresenceOutboundFrame,
  ReactionOutboundFrame,
  ActivityOutboundFrame,
  CrdtOutboundFrame,
  FileuploadOutboundFrame,
  VideohangoutOutboundFrame,
  SubscribeOutboundFrame,
} from '@connorhoehn/event-catalog/client-frames';
import type { EventPayloadMap } from '@connorhoehn/event-catalog/types';

import type {
  ChatMessage,
  PresenceEntry,
  PresenceStatus,
  Reaction,
  ActivityEvent,
} from '../../src/client/types';
import type { HangoutParticipant } from '../../src/client/useVideoHangout';
import type { Notification } from '../../src/client/useNotifications';
import type { CapabilityDescriptor } from '../../src/client/useCapability';
import type { FileUploadState } from '../../src/client/useFileUpload';

// ---------------------------------------------------------------------------
// Assertion helpers
// ---------------------------------------------------------------------------

type Assert<T extends true> = T;
type Extends<A, B> = [A] extends [B] ? true : false;
/** Mutual assignability. */
type Equivalent<A, B> = Extends<A, B> extends true ? Extends<B, A> : false;
/** Strip string/number index signatures so declared keys can be compared. */
type RemoveIndex<T> = {
  [K in keyof T as string extends K ? never : number extends K ? never : K]: T[K];
};
/** Exact key-set parity between two object types. */
type SameKeys<A, B> = Equivalent<keyof A, keyof B>;

// ---------------------------------------------------------------------------
// 1. Outbound frame-name coverage — pins the full ClientFramePayloadMap.
//
// If event-catalog ADDS an outbound client frame, `_outboundNamesPinned`
// fails until this library either implements the frame or consciously lists
// it here. If EC REMOVES/renames one, the per-frame assertions below fail.
// ---------------------------------------------------------------------------

type ExpectedOutboundFrameName =
  | 'client.chat.join'
  | 'client.chat.leave'
  | 'client.chat.send'
  | 'client.chat.history'
  | 'client.presence.subscribe'
  | 'client.presence.unsubscribe'
  | 'client.presence.set'
  | 'client.presence.get'
  | 'client.presence.heartbeat'
  | 'client.reaction.subscribe'
  | 'client.reaction.unsubscribe'
  | 'client.reaction.send'
  | 'client.reaction.getAvailable'
  | 'client.activity.subscribe'
  | 'client.activity.unsubscribe'
  | 'client.activity.getHistory'
  | 'client.crdt.subscribe'
  | 'client.crdt.unsubscribe'
  | 'client.crdt.update'
  | 'client.crdt.awareness'
  | 'client.fileupload.request-upload'
  | 'client.fileupload.complete'
  | 'client.fileupload.cancel'
  | 'client.videohangout.start'
  | 'client.videohangout.join'
  | 'client.videohangout.leave'
  | 'client.videohangout.end'
  | 'client.videohangout.toggle-video'
  | 'client.videohangout.toggle-audio'
  | 'client.subscribe.subscribe'
  | 'client.subscribe.unsubscribe';

type _outboundNamesPinned = Assert<
  Equivalent<keyof ClientFramePayloadMap, ExpectedOutboundFrameName>
>;

// ---------------------------------------------------------------------------
// 2. Outbound frames — representative shapes of what each hook actually
// sends, asserted MUTUALLY assignable with the EC payload (the EC payloads
// carry `[key: string]: unknown`, so the reverse direction holds whenever
// the declared fields agree).
//
// Send-sites carrying the same shapes are additionally annotated with
// `satisfies` in: useChat, usePresence, useReactions, useActivity,
// useFileUpload, useVideoHangout, useCRDT, useYjsDoc, useWebSocket,
// GatewaySocketProvider, GatewayProvider.
// ---------------------------------------------------------------------------

// chat (useChat join/leave lifecycle + send/history, GatewaySocketProvider
// feature auto-join). Gateway-real verbs (hub#1497): join | leave | send |
// history — channel REQUIRED on all; history limit OPTIONAL (server default
// when omitted). `leave` was declared in EC v0.3.57 (backfill), so the full
// verified verb set is asserted here and the useChat cleanup send-site
// carries its `satisfies` annotation.
type LocalChatJoin = { service: 'chat'; action: 'join'; channel: string };
type LocalChatLeave = { service: 'chat'; action: 'leave'; channel: string };
type LocalChatSend = {
  service: 'chat';
  action: 'send';
  channel: string;
  message: string;
  metadata?: Record<string, unknown>;
};
type LocalChatHistory = { service: 'chat'; action: 'history'; channel: string; limit?: number };
type _chatJoin = Assert<Equivalent<LocalChatJoin, RemoveIndex<ClientFramePayload<'client.chat.join'>>>>;
type _chatLeave = Assert<Equivalent<LocalChatLeave, RemoveIndex<ClientFramePayload<'client.chat.leave'>>>>;
type _chatSend = Assert<Equivalent<LocalChatSend, RemoveIndex<ClientFramePayload<'client.chat.send'>>>>;
type _chatHist = Assert<Equivalent<LocalChatHistory, RemoveIndex<ClientFramePayload<'client.chat.history'>>>>;
type _chatUnion = Assert<
  Extends<LocalChatJoin | LocalChatLeave | LocalChatSend | LocalChatHistory, ChatOutboundFrame>
>;

// presence (usePresence + GatewaySocketProvider feature auto-subscribe).
// Gateway-real contract (hub#1497): subscribe/unsubscribe REQUIRE channel;
// set REQUIRES status, reads { status, metadata, channels } and IGNORES a
// top-level channel (deprecated in EC; pinning uses the channels array).
type LocalPresenceSubscribe = { service: 'presence'; action: 'subscribe'; channel: string };
type LocalPresenceUnsubscribe = { service: 'presence'; action: 'unsubscribe'; channel: string };
type LocalPresenceSet = {
  service: 'presence';
  action: 'set';
  status: PresenceStatus;
  metadata: Record<string, unknown>;
  channels: string[];
};
type _presSub = Assert<Equivalent<LocalPresenceSubscribe, RemoveIndex<ClientFramePayload<'client.presence.subscribe'>>>>;
type _presUnsub = Assert<Equivalent<LocalPresenceUnsubscribe, RemoveIndex<ClientFramePayload<'client.presence.unsubscribe'>>>>;
type _presSet = Assert<Extends<LocalPresenceSet, ClientFramePayload<'client.presence.set'>>>;
// status must be REQUIRED in the EC declaration ("Status is required") —
// an EC regression back to optional status flips this assert.
type _presSetStatusRequired = Assert<
  Extends<undefined extends RemoveIndex<ClientFramePayload<'client.presence.set'>>['status'] ? true : false, false>
>;
// get / heartbeat — gateway-verified verbs declared in EC v0.3.57
// (backfill). NO hook sends them today, so they are asserted against the
// EC shapes directly (no send-site `satisfies`): get requires AT LEAST ONE
// of targetClientId/channel at runtime (either-or is not anyOf-encodable by
// EC's type generator, so both are optional in the type); heartbeat reads
// no payload fields beyond service/action.
type LocalPresenceGet = {
  service: 'presence';
  action: 'get';
  channel?: string;
  targetClientId?: string;
};
type LocalPresenceHeartbeat = { service: 'presence'; action: 'heartbeat'; channel?: string };
type _presGet = Assert<Equivalent<LocalPresenceGet, RemoveIndex<ClientFramePayload<'client.presence.get'>>>>;
type _presHeartbeat = Assert<
  Equivalent<LocalPresenceHeartbeat, RemoveIndex<ClientFramePayload<'client.presence.heartbeat'>>>
>;
type _presUnion = Assert<
  Extends<
    | LocalPresenceSubscribe
    | LocalPresenceUnsubscribe
    | LocalPresenceSet
    | LocalPresenceGet
    | LocalPresenceHeartbeat,
    PresenceOutboundFrame
  >
>;

// reaction (useReactions subscribe/unsubscribe lifecycle + react). Gateway-
// real verb (hub#1497) is 'send' — 'react' was never accepted ("Unknown
// reaction action"). The subscribe/unsubscribe lifecycle frames were
// declared in EC v0.3.57 (backfill), so the full verified verb set is
// asserted here and the useReactions send-sites carry their `satisfies`
// annotations. getAvailable is gateway-verified but sent by no hook today
// (subscribers get the emoji list in the reaction_subscribed reply), so it
// is asserted against the EC shape directly: no payload fields are read
// beyond service/action (channel ignored).
type LocalReactionSubscribe = { service: 'reaction'; action: 'subscribe'; channel: string };
type LocalReactionUnsubscribe = { service: 'reaction'; action: 'unsubscribe'; channel: string };
type LocalReactionGetAvailable = { service: 'reaction'; action: 'getAvailable'; channel?: string };
type LocalReactionSend = {
  service: 'reaction';
  action: 'send';
  channel: string;
  emoji: string;
  position?: Record<string, unknown>;
  targetId?: string;
  metadata?: Record<string, unknown>;
};
type _reactSub = Assert<
  Equivalent<LocalReactionSubscribe, RemoveIndex<ClientFramePayload<'client.reaction.subscribe'>>>
>;
type _reactUnsub = Assert<
  Equivalent<LocalReactionUnsubscribe, RemoveIndex<ClientFramePayload<'client.reaction.unsubscribe'>>>
>;
type _reactGetAvail = Assert<
  Equivalent<LocalReactionGetAvailable, RemoveIndex<ClientFramePayload<'client.reaction.getAvailable'>>>
>;
type _reactSend = Assert<Equivalent<LocalReactionSend, RemoveIndex<ClientFramePayload<'client.reaction.send'>>>>;
type _reactUnion = Assert<
  Extends<
    LocalReactionSubscribe | LocalReactionUnsubscribe | LocalReactionSend | LocalReactionGetAvailable,
    ReactionOutboundFrame
  >
>;

// activity (useActivity) — the hook sends the GATEWAY-real frames since
// 0.13.1 (hub#1492): keyed on `channelId` with history verb 'getHistory'.
// EC v0.3.56 adopted the real declarations (hub#1497), so all three frames
// — including getHistory — are asserted directly (the former
// `_actHistDiverges` pin is gone).
type LocalActivitySubscribe = { service: 'activity'; action: 'subscribe'; channel: string; channelId: string };
type LocalActivityUnsubscribe = { service: 'activity'; action: 'unsubscribe'; channel: string; channelId: string };
type LocalActivityHistory = { service: 'activity'; action: 'getHistory'; channel: string; channelId: string; limit: number };
type _actSub = Assert<Extends<LocalActivitySubscribe, ClientFramePayload<'client.activity.subscribe'>>>;
type _actUnsub = Assert<Extends<LocalActivityUnsubscribe, ClientFramePayload<'client.activity.unsubscribe'>>>;
type _actHist = Assert<Extends<LocalActivityHistory, ClientFramePayload<'client.activity.getHistory'>>>;
type _actUnion = Assert<
  Extends<LocalActivitySubscribe | LocalActivityUnsubscribe | LocalActivityHistory, ActivityOutboundFrame>
>;

// crdt (useCRDT / useYjsDoc / GatewayProvider)
type LocalCrdtSubscribe = { service: 'crdt'; action: 'subscribe'; channel: string };
type LocalCrdtUnsubscribe = { service: 'crdt'; action: 'unsubscribe'; channel: string };
type LocalCrdtUpdate = { service: 'crdt'; action: 'update'; channel: string; update: string };
