type _crdtSub = Assert<Equivalent<LocalCrdtSubscribe, RemoveIndex<ClientFramePayload<'client.crdt.subscribe'>>>>;
type _crdtUnsub = Assert<Equivalent<LocalCrdtUnsubscribe, RemoveIndex<ClientFramePayload<'client.crdt.unsubscribe'>>>>;
type _crdtUpdate = Assert<Equivalent<LocalCrdtUpdate, RemoveIndex<ClientFramePayload<'client.crdt.update'>>>>;
type _crdtAwareness = Assert<Equivalent<LocalCrdtAwareness, RemoveIndex<ClientFramePayload<'client.crdt.awareness'>>>>;
type _crdtUnion = Assert<
  Extends<LocalCrdtSubscribe | LocalCrdtUnsubscribe | LocalCrdtUpdate | LocalCrdtAwareness, CrdtOutboundFrame>
>;

