// ---------------------------------------------------------------------------
// 3. Inbound hook-contract frames — the 12 ws.* declarations EC added for
// the hook contracts (presence:joined/left, fileupload:*, videohangout:*,
// notification:*, capability/feature-flag updated).
// ---------------------------------------------------------------------------

// presence:joined → PresenceEntry (usePresence roster entries).
// EC `client` is pre-parse (only clientId required, status is plain string);
// PresenceEntry is post-parse (asPresenceEntry fills defaults, status is the
// documented PresenceStatus vocabulary). Assert key parity + local→EC.
type EcPresenceJoinedClient = RemoveIndex<EventPayloadMap['ws.presence.joined']['client']>;
type _presenceEntryKeys = Assert<SameKeys<PresenceEntry, EcPresenceJoinedClient>>;
type _presenceEntryFields = Assert<Extends<PresenceEntry, EcPresenceJoinedClient>>;
type _presenceStatusIsString = Assert<Extends<PresenceStatus, EcPresenceJoinedClient['status']>>;

// presence:left → { channel, clientId } (usePresence removal path).
type EcPresenceLeft = EventPayloadMap['ws.presence.left'];
type _presenceLeft = Assert<Extends<{ type: 'presence:left'; channel: string; clientId: string }, EcPresenceLeft>>;

// fileupload:progress / scanning / cancelled → fields useFileUpload reads.
type EcFupProgress = EventPayloadMap['ws.fileupload.progress'];
type _fupProgId = Assert<Extends<EcFupProgress['id'], string>>;
type _fupProgPct = Assert<Extends<EcFupProgress['progress'], FileUploadState['progress'] & number>>;
type _fupScanning = Assert<Extends<EventPayloadMap['ws.fileupload.scanning']['id'], string>>;
type _fupCancelled = Assert<Extends<EventPayloadMap['ws.fileupload.cancelled']['id'], string>>;

// videohangout:participant → HangoutParticipant.
// Same pre/post-parse split: EC marks videoOn/audioOn/joinedAt optional on
// the wire; asParticipant() defaults them, so they are required locally.
type EcHangoutParticipant = RemoveIndex<EventPayloadMap['ws.videohangout.participant']['participant']>;
type _participantKeys = Assert<SameKeys<HangoutParticipant, EcHangoutParticipant>>;
type _participantFields = Assert<Extends<HangoutParticipant, EcHangoutParticipant>>;
type _participantRole = Assert<Equivalent<HangoutParticipant['role'], EcHangoutParticipant['role']>>;

// videohangout:media → media-toggle fanout fields.
type EcHangoutMedia = EventPayloadMap['ws.videohangout.media'];
type _media = Assert<
  Extends<
    { type: 'videohangout:media'; channel: string; clientId: string; videoOn: boolean; audioOn: boolean },
    EcHangoutMedia
  >
>;

// notification:new / read / bulk-update → Notification (useNotifications).
type EcNotificationPayload = RemoveIndex<EventPayloadMap['ws.notification.new']['payload']>;
type _notificationKeys = Assert<SameKeys<Notification, EcNotificationPayload>>;
type _notificationFields = Assert<Extends<Notification, EcNotificationPayload>>;
type _notificationRead = Assert<Extends<EventPayloadMap['ws.notification.read']['payload']['id'], string>>;
type EcBulkNotification = RemoveIndex<
  EventPayloadMap['ws.notification.bulk-update']['payload']['notifications'][number]
>;
type _notificationBulk = Assert<Extends<Notification, EcBulkNotification>>;

// capability:updated → CapabilityDescriptor (useCapability).
type EcCapabilityPayload = RemoveIndex<EventPayloadMap['ws.capability.updated']['payload']>;
type _capabilityKeys = Assert<SameKeys<CapabilityDescriptor, EcCapabilityPayload>>;
type _capability = Assert<Equivalent<CapabilityDescriptor, EcCapabilityPayload>>;

// feature-flag:updated → useFeatureFlag's (module-private) payload mirror.
type LocalFeatureFlagPayload = {
  name: string;
  enabled: boolean;
  variant?: string;
  metadata?: Record<string, unknown>;
};
type _featureFlag = Assert<Equivalent<LocalFeatureFlagPayload, RemoveIndex<EventPayloadMap['ws.feature-flag.updated']['payload']>>>;

// ---------------------------------------------------------------------------
// 3b. Gateway SEND-BACK envelopes — the action-frame envelopes useChat /
// usePresence / useReactions PARSE (divergence note b, RESOLVED by EC 0.3.58).
//
// EC 0.3.58 declared the complete gateway send-back set per the service
// implementations the gateway runs (websocket-gateway/node_modules/
// @connorhoehn/realtime-modules/dist/{chat,presence,reactions,crdt}/). The
// hooks parse these envelopes payload-first; below we assert that the envelope
// LITERALS the hooks branch on (msg.type === 'chat' && msg.action ===
// 'message', etc.) match the EC declarations, and that the per-frame payload
// slot the hook extracts (message / presence / data) accepts the local
// post-parse type (ChatMessage / PresenceEntry / Reaction). The EC payloads
// model the PRE-PARSE wire (the inner object is Record<string, unknown>, so
// the as*() guards' POST-PARSE local types are assignable into it).

// The hooks' public payload types are interfaces (no index signature), so they
// are NOT whole-object assignable into the EC pre-parse slots (which are loose
// Record<string, unknown>). Following the §3 pattern, each frame is asserted in
// two parts: (1) the ENVELOPE discriminants (type/action + key fields) the hook
// branches on match the EC declaration; (2) the local payload type the as*()
// guard produces is a valid object for the EC slot, checked field-wise via the
// existing _activityFields / _notificationFields / _reactionCore style.

// chat — { type:'chat', action:'message', message } / { ..., action:'history',
// messages } (useChat gateway-real branch).
type EcChatMessageEnvelope = EventPayloadMap['ws.chat.message'];
type EcChatHistoryEnvelope = EventPayloadMap['ws.chat.history'];
type _chatMsgType = Assert<Equivalent<EcChatMessageEnvelope['type'], 'chat'>>;
type _chatMsgAction = Assert<Equivalent<EcChatMessageEnvelope['action'], 'message'>>;
type _chatMsgChannel = Assert<Extends<EcChatMessageEnvelope['channel'], string>>;
type _chatMsgSlot = Assert<Extends<ChatMessage, RemoveIndex<EcChatMessageEnvelope['message']>>>;
type _chatHistType = Assert<Equivalent<EcChatHistoryEnvelope['action'], 'history'>>;
type _chatHistSlot = Assert<Extends<ChatMessage, RemoveIndex<EcChatHistoryEnvelope['messages'][number]>>>;

// presence — { type:'presence', action:'subscribed', presence: PresenceEntry[] }
// / { action:'set'|'update', presence: PresenceEntry } (usePresence gateway-real
// branch). presence is optional on the wire (server may omit); assert the slot
// accepts PresenceEntry once present.
type EcPresenceSubscribedEnvelope = EventPayloadMap['ws.presence.subscribed'];
type EcPresenceSetEnvelope = EventPayloadMap['ws.presence.set'];
type EcPresenceUpdateEnvelope = EventPayloadMap['ws.presence.update'];
type _presSubAction = Assert<Equivalent<EcPresenceSubscribedEnvelope['action'], 'subscribed'>>;
type _presSubChannel = Assert<Extends<EcPresenceSubscribedEnvelope['channel'], string>>;
type _presSubSlot = Assert<
  Extends<PresenceEntry, RemoveIndex<NonNullable<EcPresenceSubscribedEnvelope['presence']>[number]>>
>;
type _presSetAction = Assert<Equivalent<EcPresenceSetEnvelope['action'], 'set'>>;
type _presSetSlot = Assert<Extends<PresenceEntry, RemoveIndex<NonNullable<EcPresenceSetEnvelope['presence']>>>>;
type _presUpdateAction = Assert<Equivalent<EcPresenceUpdateEnvelope['action'], 'update'>>;
type _presUpdateSlot = Assert<Extends<PresenceEntry, RemoveIndex<NonNullable<EcPresenceUpdateEnvelope['presence']>>>>;

// reaction — { type:'reaction', action:'reaction_received', data: Reaction }
// (useReactions gateway-real branch). The data slot accepts the local Reaction
// post-parse type; the ack envelopes (reaction_unsubscribed / available_reactions
// — newly declared in 0.3.58) are pinned so the "no state change needed" branch
// stays contract-covered.
type EcReactionReceivedEnvelope = EventPayloadMap['ws.reaction.received'];
type _reactReceivedType = Assert<Equivalent<EcReactionReceivedEnvelope['type'], 'reaction'>>;
type _reactReceivedAction = Assert<Equivalent<EcReactionReceivedEnvelope['action'], 'reaction_received'>>;
type _reactReceivedSlot = Assert<Extends<Reaction, RemoveIndex<EcReactionReceivedEnvelope['data']>>>;
type _reactUnsubAck = Assert<
  Extends<EventPayloadMap['ws.reaction.unsubscribed']['action'], 'reaction_unsubscribed'>
>;
type _reactAvailableAck = Assert<
  Extends<EventPayloadMap['ws.reaction.available']['data']['reactions'], Record<string, unknown>>
>;
type _reactSentAck = Assert<
  Extends<EventPayloadMap['ws.reaction.sent']['data']['reactionId'], string>
>;

// crdt — { type:'crdt:awareness', channel, updates:[{ clientId, update }] }
// (newly declared in 0.3.58; the dist AwarenessCoalescer emit shape, distinct
// from the historical ws.crdt.awareness-batch). Pin the envelope literal +
// per-entry fields.
type EcCrdtAwarenessEnvelope = EventPayloadMap['ws.crdt.awareness'];
type EcCrdtAwarenessEntry = RemoveIndex<EcCrdtAwarenessEnvelope['updates'][number]>;
type _crdtAwarenessType = Assert<Equivalent<EcCrdtAwarenessEnvelope['type'], 'crdt:awareness'>>;
type _crdtAwarenessChannel = Assert<Extends<EcCrdtAwarenessEnvelope['channel'], string>>;
type _crdtAwarenessEntry = Assert<
  Extends<{ clientId: string; update: string }, EcCrdtAwarenessEntry>
>;

// ---------------------------------------------------------------------------
// 4. Known divergences (documented, deliberately NOT "fixed" in Wave A3 —
// each fix would be a runtime behavior change, not a doc/type correction).
//
// a) useActivity inbound envelope — RESOLVED in 0.13.1 (hub#1492). The hook
//    now parses the gateway-real envelopes
//      { type: 'activity:event', payload: { eventType, detail, ... } }
//      { type: 'activity', action: 'history', events, channelId }
//    payload-first, with the old flat shapes
//      { type: 'activity:event', channel, ...ActivityEvent }
//      { type: 'activity:history', channel, events: [...] }
//    kept as a legacy fallback. Live activity:event frames carry NO channel
//    field (single global 'activity:broadcast' channel; the gateway scopes
//    delivery via the channel subscription), so the hook accepts every
//    activity:event on the socket and only channel-filters legacy flat
//    frames + history responses (channelId).
//
// b) RESOLVED in EC v0.3.58 (2026-06-12). useChat / useReactions /
//    usePresence parse the gateway-real action-frame envelopes
//    ({ type: 'chat', action: 'message'|'history' }, { type: 'reaction',
//    action: 'reaction_received', data }, { type: 'presence', action:
//    'subscribed'|'set'|'update'|'offline' }) payload-first, with the old
//    flat shapes (chat:message / chat:history / reaction:new /
//    reaction:history / presence:state / presence:joined / presence:updated
//    / presence:left) kept as a legacy fallback. EC 0.3.58 declared the
//    COMPLETE gateway send-back set per the service implementations the
//    gateway runs (dist/{chat,presence,reactions,crdt}/) — including the
//    previously-missing reaction/reaction_unsubscribed, available_reactions
//    and crdt:awareness frames, and reconciled reaction_subscribed/sent +
//    ws.error against ground truth. §3b above now asserts the hooks' parsers
//    against the full inbound-envelope set directly (the former
//    "assertions remain TODO" caveat is gone).
//
// c) RESOLVED in EC v0.3.57 (backfill): chat/leave (useChat cleanup) and
//    reaction/subscribe + reaction/unsubscribe (useReactions lifecycle) are
//    now declared; their send-sites carry `satisfies` annotations like
//    their siblings, and §2 asserts them directly. EC also backfilled the
//    hook-less gateway-verified verbs reaction/getAvailable +
//    presence/get + presence/heartbeat (asserted in §2 against the EC
//    shapes; no send-site exists to annotate).
//
// d) RESOLVED in EC v0.3.56 (hub#1497): client.activity.* now declares the
//    gateway-real `channelId` + 'getHistory' frames; the former
//    `_actHistDiverges` pin in §2 was replaced by the direct `_actHist`
//    assertion and useActivity.loadHistory regained its `satisfies`
//    annotation.
// ---------------------------------------------------------------------------

// ActivityEvent field shape vs EC's ws.activity.event payload (post-parse →
// pre-parse direction + key parity), envelope divergence notwithstanding.
type EcActivityEventPayload = RemoveIndex<EventPayloadMap['ws.activity.event']['payload']>;
type _activityKeys = Assert<SameKeys<ActivityEvent, EcActivityEventPayload>>;
type _activityFields = Assert<Extends<ActivityEvent, EcActivityEventPayload>>;

// Reaction core wire fields vs the ws.reaction.received data block. The full
// received-envelope assertion now lives in §3b (_reactReceivedEnvelope); this
// field-level check is retained as the post-parse → pre-parse data-slot pin.
type EcReactionData = RemoveIndex<EventPayloadMap['ws.reaction.received']['data']>;
type _reactionCore = Assert<Extends<Reaction, EcReactionData>>;

// ChatMessage is now asserted against the ws.chat.message / ws.chat.history
// envelope payload slots in §3b; this id-level pin keeps the import
// load-bearing if the type is renamed.
type _chatMessageStillExported = Assert<Extends<ChatMessage['id'], string>>;

// ---------------------------------------------------------------------------
// Runtime stub — keeps jest happy; the real assertions are the types above.
// A representative frame per service exercises that the EC types describe
// constructible values (and that the type-only imports erased at runtime).
// ---------------------------------------------------------------------------

describe('contract conformance (compile-time)', () => {
  it('EC client-frame payloads are constructible from hook frame shapes', () => {
    const chatSend: ClientFramePayload<'client.chat.send'> = {
      service: 'chat',
      action: 'send',
      channel: 'chat:general',
      message: 'hello',
    };
    const reactionSend: ClientFramePayload<'client.reaction.send'> = {
      service: 'reaction',
      action: 'send',
      channel: 'chat:general',
      emoji: '🔥',
    };
    const resub: ClientFramePayload<'client.subscribe.subscribe'> = {
      service: 'subscribe',
      action: 'subscribe',
      channel: 'doc:readme',
    };
    expect(chatSend.service).toBe('chat');
    expect(reactionSend.action).toBe('send');
    expect(resub.channel).toBe('doc:readme');
  });

  it('type-only event-catalog imports leave no runtime require', () => {
    // If the import at the top of this file were not type-only, jest's
    // module registry would contain the EC package after loading this file.
    const ecRuntime = Object.keys(require.cache).filter((k) =>
      k.includes(`${'@connorhoehn'}/event-catalog`),
    );
    expect(ecRuntime).toEqual([]);
  });
});
